/bin/bash -c "python3 - <<'PY'
from pathlib import Path
import re,statistics,math
p=Path('tmp/pdfs/page-22.txt').read_text()
for title,chunk in zip(['positive','negative','neutral'],p.split('Prompts of Experiment 1 - ')[1:]):
 nums=[int(s) for s in re.findall(r'(\\d+)\\s*:\\s*[A-D]',chunk)]
 print('Glubbing list',title,'N',len(nums),'mean',statistics.mean(nums),'SD',statistics.stdev(nums))
rows=[]
for l in Path('tmp/pdfs/page-34.txt').read_text().splitlines():
 if re.fullmatch(r'\\d+\\.\\d+(?:\\s+\\d+\\.\\d+){7}',l):
  rows.append([float(s) for s in l.split()])
print('Prototype rows',len(rows))
pos=neg=ties=deg=0
for r in rows:
 a,ideal,s=r[2],r[3],r[7]
 if a==ideal: deg+=1
 elif (s-a)*(ideal-a)>0: pos+=1
 elif (s-a)*(ideal-a)<0: neg+=1
 else:ties+=1
print('Prototype positive negative ties degenerate',pos,neg,ties,deg)
for c in range(1,9):
 rs=[r for r in rows if r[0]==c]
 print('Prototype means',c,*[round(statistics.mean(r[j] for r in rs),4) for j in [2,3,7]])
med=[]
for l in Path('tmp/pdfs/page-30.txt').read_text().splitlines():
 m=re.search(r'(\\d+\\.\\d+)\\s+(\\d+\\.\\d+)\\s+(\\d+\\.\\d+)\\s*"'$'"',l)
 if m:med.append([float(x) for x in m.groups()])
print('Medical row count',len(med),'positive',sum((s-a)*(i-a)>0 for a,i,s in med),'negative',sum((s-a)*(i-a)<0 for a,i,s in med),'ties',sum(s==a for a,i,s in med))
def p_bin(k,n):
 return min(1,2*sum(math.comb(n,j) for j in range(k,n+1))/2**n)
for k,n in [(304,444),(340,500),(26,35),(39,46),(38,46)]:
 print('two-sided binomial',k,n,p_bin(k,n))
PY"
